// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0) && caddress != address(c) && caddress != address(this));
        AdversarialToken caller = new AdversarialToken();
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.prank(address(this));
        bool success = c.transfer(from, address(caller), _tos, v);
        assertTrue(caller.callCount() == _tos.length);
    }
}

contract AdversarialToken {
    uint public callCount;
    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }
}
